/* Historia — contenu : Francs & Carolingiens */
HISTORIA_CONTENT["carolingiens"] = {
  intro: "Du baptême de Clovis à l'empire de Charlemagne, puis à l'éclatement du monde carolingien sous les coups des Vikings : cinq siècles où naît l'Occident chrétien.",
  levels: [
    {
      title: "Clovis, le roi qui change l'Histoire",
      lesson: { d: "481 – 511", t: "Clovis, de Tournai au baptême de Reims", hook: "Tournai, 1653 : un ouvrier heurte de l'or sous la terre. Il vient de trouver la tombe d'un roi franc, père d'un garçon qui va changer l'Histoire. Son nom : Clovis.", p: "Quand l'ouvrier ramène à la surface un anneau-sceau gravé du nom de Childéric, des armes, des bijoux d'or et de grenat et de petites abeilles d'or, il ne sait pas qu'il touche aux origines de la France. Childéric est le père de Clovis. À sa mort, en 481, son fils est à peine sorti de l'adolescence et ne règne que sur un petit royaume franc autour de Tournai. Rien ne laisse prévoir qu'il changera le visage de l'Occident.\n\n## Un jeune roi dans une Gaule en morceaux\n\nPour comprendre Clovis, il faut oublier la carte de la France. Au Ve siècle, l'Empire romain d'Occident s'effondre et la Gaule se découpe : des Wisigoths dans le sud-ouest, des Burgondes dans la vallée du Rhône, des Alamans le long du Rhin, des Francs dans le nord. Un seul morceau relève encore, de loin, de Rome : le domaine de Syagrius, entre Seine et Loire. Vers 486, Clovis l'attaque à Soissons et l'emporte. Syagrius s'enfuit chez les Wisigoths, qui finissent par le livrer ; il est mis à mort.\n\nC'est à Soissons que Grégoire de Tours, évêque écrivant un siècle plus tard, place une scène célèbre. Après la bataille, un soldat brise d'un coup de hache un précieux vase d'église, alors que Clovis cherchait à le rendre à l'évêque. Le roi ravale sa colère. Un an plus tard, à la revue des troupes, il reproche au même homme ses armes mal tenues, jette sa hache à terre et, quand l'homme se baisse, lui fend le crâne : « Voilà ce que tu as fait au vase de Soissons. » Que retenir de cette histoire ? Qu'un roi franc doit se faire respecter d'hommes libres, armés, qui ne s'inclinent pas devant n'importe qui.\n\n## La reine, l'évêque et le baptême\n\nVers 493, Clovis épouse Clotilde, nièce du roi burgonde Gondebaud. Elle est catholique, comme la plupart des Gallo-Romains, alors que les rois wisigoths, burgondes et ostrogoths suivent l'arianisme, une doctrine qui fait du Christ un être subordonné au Père. Selon Grégoire de Tours, Clotilde insiste auprès de son mari. Il hésite, jusqu'au jour où, en difficulté dans une bataille contre les Alamans, il promet de se convertir s'il l'emporte. Il gagne. La tradition a retenu Tolbiac comme lieu du combat, mais le lieu et la date restent discutés.\n\nLe baptême a lieu à Reims, des mains de l'évêque Remi, à Noël selon la tradition. Grégoire de Tours le place en 496, les historiens hésitent aujourd'hui entre 496 et 508. Il prête à Remi cette formule : « Courbe la tête, fier Sicambre ; adore ce que tu as brûlé, brûle ce que tu as adoré. » Le choix est un coup de maître politique : en devenant catholique, Clovis gagne les évêques, qui tiennent les villes et savent administrer. Pour eux, mieux vaut un roi de leur foi que des souverains ariens.\n\n## Vouillé, Paris et un héritage à partager\n\nUne vingtaine d'années après Soissons, Clovis se tourne vers le sud. Il rencontre les Wisigoths d'Alaric II à Vouillé, près de Poitiers ; Alaric est tué et son armée s'effondre. Le sud-ouest de la Gaule passe presque entièrement aux Francs. L'empereur d'Orient Anastase envoie ensuite à Clovis les insignes de consul honoraire, un titre qui flatte le roi et le fait entrer dans le cercle des pouvoirs reconnus. Il s'installe à Paris, la ville de sainte Geneviève.\n\nClovis meurt à Paris en 511, vers quarante-cinq ans, et repose dans la basilique des Saints-Apôtres qu'il avait fait bâtir. Les Francs ne connaissent pas l'idée d'un État qui se transmet d'un seul bloc : le royaume est un héritage familial. Ses quatre fils, Thierry, Clodomir, Childebert et Clotaire, le partagent, puis se disputeront. Son nom, Chlodowig, donnera Clovis et Louis ; celui des Francs finira par désigner tout le pays. À Reims, la cathédrale rappelle encore ce baptême qui a fait de la royauté franque une royauté chrétienne.", fun: ["Clovis et Louis, c'est le même prénom ! Le nom germanique Chlodowig a évolué en deux directions, ce qui fait de Louis XIV un lointain homonyme du vainqueur de Soissons.","Dans la tombe de Childéric, on a trouvé environ trois cents petites abeilles d'or. On raconte que Napoléon s'en est inspiré pour choisir l'abeille comme emblème de son sacre."] },
      items: [
        { type: "qcm", q: "Comment s'appelle le père de Clovis, enterré à Tournai avec un riche mobilier funéraire ?", c: "Childéric Ier", w: ["Mérovée", "Clotaire Ier", "Gondebaud"], e: "Sa tombe, découverte à Tournai en 1653, contenait son anneau-sceau portant son nom, des armes et de riches bijoux d'or et de grenat." },
        { type: "qcm", q: "Quelle princesse burgonde, catholique, épouse Clovis et l'encourage à se convertir ?", c: "Clotilde", w: ["Radegonde", "Brunehaut", "Frédégonde"], e: "Clotilde, nièce du roi burgonde Gondebaud, a prié pour la conversion de son mari. L'Église l'a ensuite vénérée comme sainte." },
        { type: "qcm", q: "Quel évêque baptise Clovis à Reims ?", c: "Remi", w: ["Martin", "Denis", "Germain"], e: "Remi, évêque de Reims, est le conseiller religieux du roi. Pour les Francs, Reims restera durablement liée à la royauté et au sacre." },
        { type: "qcm", q: "Contre quel peuple Clovis remporte-t-il la bataille de Vouillé ?", c: "Les Wisigoths", w: ["Les Burgondes", "Les Ostrogoths", "Les Alamans"], e: "Le roi wisigoth Alaric II est tué. Cette victoire donne aux Francs la plus grande partie du sud-ouest de la Gaule." },
        { type: "qcm", q: "Quelle ville Clovis choisit-il comme résidence principale à la fin de sa vie ?", c: "Paris", w: ["Lyon", "Toulouse", "Bordeaux"], e: "Il y fait construire une basilique dédiée aux saints Pierre et Paul, où il est enterré en 511. Elle deviendra plus tard Sainte-Geneviève." },
        { type: "tf", q: "En choisissant le catholicisme, Clovis se distingue de la plupart des autres rois barbares de son temps.", a: true, e: "Wisigoths, Burgondes et Ostrogoths étaient ariens. Le catholicisme de Clovis lui vaut l'appui des évêques de Gaule." },
        { type: "tf", q: "À sa mort, Clovis laisse son royaume entier à son seul fils aîné.", a: false, e: "Selon la coutume franque, le royaume est partagé entre ses quatre fils : Thierry, Clodomir, Childebert et Clotaire." },
        { type: "order", q: "Remets ces événements dans l'ordre chronologique.", items: [{ t: "Mort de Childéric, père de Clovis", y: "481" }, { t: "Victoire de Clovis sur Syagrius à Soissons", y: "486" }, { t: "Mort de Clovis à Paris", y: "511" }, { t: "Clotaire Ier réunit le royaume franc", y: "558" }] },
        { type: "match", q: "Associe chaque lieu à l'épisode de la vie de Clovis.", pairs: [["Soissons", "Victoire sur Syagrius"], ["Reims", "Baptême par l'évêque Remi"], ["Vouillé", "Défaite des Wisigoths"], ["Tournai", "Tombe de son père Childéric"]] },
        { type: "year", q: "En quelle année Clovis bat-il les Wisigoths à Vouillé ?", y: 507, min: 470, max: 600, tol: 1, e: "La bataille a lieu près de Poitiers en 507. Selon Grégoire de Tours, Clovis reçoit ensuite de l'empereur d'Orient Anastase les insignes de consul honoraire." }
      ]
    },
    {
      title: "Rois, reines et maires du palais",
      lesson: { d: "VIe – VIIe siècle", t: "Les Mérovingiens : rois, reines et maires du palais", hook: "Deux reines qui se détestent, des rois aux cheveux longs, des enfants sur le trône et, dans l'ombre, un maire qui attend son heure : bienvenue dans le monde des Mérovingiens.", p: "Imagine que tu hérites d'un royaume, et que tes trois frères aussi. C'est le système franc : à la mort du roi, ses fils se partagent les terres, comme on partage une ferme entre cousins. Après Clovis, ce partage se répète à chaque génération, et les morceaux changent de forme au gré des morts et des guerres. Peu à peu, trois grands ensembles se dessinent : la Neustrie à l'ouest, avec Soissons et Paris, l'Austrasie à l'est, avec Metz et Reims, et la Burgondie dans le sud-est. Les rois s'allient, se trahissent, se font la guerre, parfois entre frères.\n\n## Deux reines, une guerre de famille\n\nLe plus célèbre de ces conflits oppose deux femmes. Frédégonde, d'origine modeste selon Grégoire de Tours, devient l'épouse du roi de Neustrie Chilpéric Ier. Brunehaut, princesse wisigothe, est celle du roi d'Austrasie Sigebert. Tout s'envenime quand la sœur de Brunehaut, mariée à Chilpéric, est retrouvée morte et que Frédégonde prend sa place. Sigebert est assassiné en 575 et les chroniqueurs accusent Frédégonde. Brunehaut, elle, gouverne ensuite au nom de son fils, puis de ses petits-fils.\n\nEn 613, très âgée, Brunehaut tombe aux mains de Clotaire II, fils de Frédégonde. Il la fait mourir de façon atroce : selon les récits, elle est attachée à un cheval indompté. Clotaire II réunit alors les trois royaumes, mais doit laisser de larges pouvoirs aux grandes familles qui l'ont aidé. Voilà une constante de l'époque : ce sont les aristocrates qui font et défont les rois.\n\n## Le temps des rois chevelus\n\nChez les Francs, la longue chevelure est un emblème. Les princes mérovingiens la portent sur les épaules, alors que les autres se coupent les cheveux. Couper celle d'un prince, c'est le priver de ses droits au trône : certains fils de rois ont fini ainsi au couvent. Pour connaître la vie de cette cour, nous dépendons surtout de Grégoire de Tours, évêque de Tours, mort en 594. Son Histoire des Francs mêle miracles, ruses de palais et crimes avec un tel talent qu'elle se lit presque comme un roman noir.\n\nCe monde n'est pas seulement brutal. Radegonde, princesse de Thuringe, capturée enfant puis mariée au roi Clotaire Ier, quitte la cour et fonde à Poitiers le monastère Sainte-Croix, où elle accueille le poète Venance Fortunat. Bathilde, jeune Anglo-Saxonne arrivée en Gaule comme esclave, épouse le roi Clovis II, gouverne comme régente et agit contre la vente de chrétiens comme esclaves. Éloi, lui, est un orfèvre de talent : il travaille pour le roi, dirige la monnaie, puis devient évêque de Noyon.\n\n## Dagobert, puis les rois qui ne gouvernent plus\n\nDagobert Ier, qui règne à partir de 629, est généralement considéré comme le dernier roi mérovingien à gouverner vraiment. Il s'entoure d'Éloi, favorise l'abbaye de Saint-Denis et y repose. La chanson du « bon roi Dagobert » à la culotte à l'envers n'a rien d'historique : elle date de bien plus tard. Après lui, les rois montent souvent sur le trône enfants et meurent jeunes. La tradition les appelle les « rois fainéants », une étiquette que les historiens jugent aujourd'hui exagérée.\n\nÉginhard décrit le dernier de ces rois se montrant au peuple, barbe et cheveux longs, assis sur son trône, avant de repartir sur un chariot tiré par des bœufs. Le vrai pouvoir est ailleurs : chez les maires du palais, d'abord simples intendants de la maison royale, qui commandent l'armée, distribuent terres et charges et gagnent la fidélité des guerriers. En 687, à Tertry, Pépin de Herstal, maire d'Austrasie, bat les Neustriens et domine tout le royaume. La famille des futurs Carolingiens est en place.", fun: ["Dans la préface de son Histoire des Francs, Grégoire de Tours se plaint que la culture des lettres se perde dans les villes de Gaule, et il s'excuse presque de son latin simple.","Le mot « mérovingien » vient de Mérovée, un chef franc du Ve siècle dont on ne sait presque rien, présenté par la tradition comme un ancêtre de Clovis.","Bathilde, esclave devenue reine, a fini par être honorée comme sainte par l'Église. Elle a fondé ou soutenu plusieurs monastères, dont celui de Chelles."] },
      items: [
        { type: "qcm", q: "Quel roi mérovingien, enterré à Saint-Denis, est resté célèbre par une chanson populaire où il est conseillé par saint Éloi ?", c: "Dagobert Ier", w: ["Clotaire II", "Childéric III", "Chilpéric Ier"], e: "La chanson date de bien plus tard, mais Éloi a réellement existé : orfèvre et conseiller de Dagobert, il devient évêque de Noyon." },
        { type: "qcm", q: "Qui exerce le véritable pouvoir à la fin de la période mérovingienne ?", c: "Les maires du palais", w: ["Les comtes de Paris", "Les missi dominici", "Les sénéchaux"], e: "D'abord simples intendants de la maison du roi, les maires du palais commandent l'armée et distribuent les terres et les charges." },
        { type: "qcm", q: "Quel signe distingue traditionnellement les rois mérovingiens des autres Francs ?", c: "Leurs longs cheveux", w: ["Une barbe tressée", "Un casque doré", "Un anneau de fer"], e: "Les cheveux longs symbolisaient leur lignée royale. Couper la chevelure d'un prince, c'était l'écarter du trône." },
        { type: "qcm", q: "Quelle reine d'Austrasie, longtemps rivale de Frédégonde, est suppliciée à la fin de sa vie par Clotaire II ?", c: "Brunehaut", w: ["Clotilde", "Radegonde", "Bathilde"], e: "Brunehaut, princesse wisigothe, a gouverné en Austrasie au nom de ses descendants. Clotaire II la fait mourir de façon atroce, en 613." },
        { type: "qcm", q: "Quel évêque a écrit l'Histoire des Francs, principale source sur les premiers Mérovingiens ?", c: "Grégoire de Tours", w: ["Isidore de Séville", "Bède le Vénérable", "Éginhard"], e: "Grégoire de Tours (mort en 594) raconte aussi bien les miracles que les crimes des rois. Sans lui, nous saurions très peu de choses sur cette époque." },
        { type: "tf", q: "Le royaume mérovingien est divisé en plusieurs ensembles, dont la Neustrie et l'Austrasie.", a: true, e: "La Neustrie couvre l'ouest du royaume, l'Austrasie l'est, avec des villes comme Metz et Reims. Leur rivalité traverse tout le VIIe siècle." },
        { type: "tf", q: "Dagobert Ier est le dernier roi de la dynastie mérovingienne.", a: false, e: "Le dernier est Childéric III, déposé en 751, plus d'un siècle après Dagobert. Après 639, les rois mérovingiens perdent peu à peu l'essentiel du pouvoir." },
        { type: "order", q: "Remets ces événements chez les Mérovingiens dans l'ordre chronologique.", items: [{ t: "Mort de Grégoire de Tours", y: "594" }, { t: "Mort de la reine Brunehaut", y: "613" }, { t: "Pépin de Herstal vainc les Neustriens à Tertry", y: "687" }, { t: "Mort de Pépin de Herstal", y: "714" }] },
        { type: "match", q: "Associe chaque figure mérovingienne à son rôle.", pairs: [["Éloi", "Orfèvre devenu évêque de Noyon"], ["Dagobert", "Roi inhumé à Saint-Denis"], ["Pépin de Herstal", "Maire du palais d'Austrasie"], ["Radegonde", "Reine fondatrice d'un monastère"]] },
        { type: "year", q: "En quelle année meurt le roi Dagobert Ier ?", y: 639, min: 580, max: 730, tol: 2, e: "Il meurt en 639, à environ trente-cinq ans. Après lui, les rois sont souvent des enfants et les maires du palais gouvernent à leur place." }
      ]
    },
    {
      title: "Charles Martel et la bataille de Poitiers",
      lesson: { d: "714 – 741", t: "Charles Martel, maître du royaume", hook: "Un prisonnier s'évade, prend le pouvoir contre sa belle-famille, puis arrête une armée venue du sud. Voici le roman de Charles, que la postérité appellera Martel.", p: "En 714, Pépin de Herstal meurt et laisse le royaume sans chef clair. Sa veuve Plectrude veut garder le pouvoir pour ses petits-fils, encore des enfants. Mais Pépin avait un autre fils, Charles, né d'une seconde union. Plectrude l'enferme. Charles s'évade, rassemble des partisans et enchaîne les victoires, dont celle de Vinchy, en 717. Quelques années plus tard, il dirige la Neustrie, l'Austrasie et la Burgondie, au nom d'un roi mérovingien qui n'a plus que le titre.\n\n## Le prisonnier devenu maître\n\nCharles est un homme de guerre. Presque chaque année, il part en campagne : contre les Frisons, les Saxons, les Alamans, les Bavarois. Il a aussi compris l'intérêt de l'Église. Il protège le missionnaire anglo-saxon Boniface, envoyé en Germanie par le pape, qui fonde des évêchés et des monastères. Selon la tradition, Boniface abat un grand chêne sacré des païens, près de Geismar, pour montrer que leurs dieux ne le punissent pas.\n\n## Poitiers : une victoire, deux lectures\n\nAu sud, un autre monde avance. Depuis 711, des armées musulmanes ont conquis la plus grande partie de l'Espagne wisigothique, et Narbonne est tombée en 719. Le duc d'Aquitaine Eudes les a battues à Toulouse en 721, mais en 732 le gouverneur Abd al-Rahman franchit les Pyrénées, écrase Eudes près de la Garonne et pille l'Aquitaine. Eudes, vaincu, appelle son vieux rival Charles à l'aide.\n\nLa rencontre a lieu entre Tours et Poitiers, à l'automne, selon la tradition. Une chronique espagnole écrite en 754 décrit les Francs, immobiles, comme un mur et comme une barrière de glace. Abd al-Rahman est tué, et les survivants se retirent vers le sud. Les textes de l'époque en disent peu. Plus tard, on a vu dans cette bataille le salut de la chrétienté. Les historiens d'aujourd'hui y voient plutôt une grosse expédition de pillage arrêtée, et non un choc de civilisations. Charles, lui, n'en finit pas là : il échoue devant Narbonne en 737, et les musulmans resteront en Septimanie encore une vingtaine d'années.\n\n## Des terres pour des guerriers\n\nPour garder une armée fidèle, il faut la payer. Charles confie des terres en bénéfice à des hommes liés à lui par serment, les vassaux, et certaines de ces terres appartenaient à l'Église. Les évêques ne l'oublieront pas : un siècle plus tard, une lettre rapporte la vision d'un saint qui aurait vu Charles tourmenter en enfer. Quand le roi Thierry IV meurt en 737, Charles ne lui donne pas de successeur. Il est le vrai maître, sans en porter le nom. Quand le pape lui demande son aide contre les Lombards, il n'intervient pas : leur roi Liutprand l'avait aidé contre les musulmans en Provence.\n\nCharles meurt à Quierzy en 741 et repose à Saint-Denis. Le surnom de « Martel », le marteau, n'apparaît que bien après lui. Il laisse le pouvoir à ses fils Carloman et Pépin, qui franchiront le dernier pas : prendre la couronne. Charles est le grand-père de Charlemagne, et c'est de son nom latin, Carolus, que la dynastie tirera le sien.", fun: ["Vers 858, des évêques rapportent la vision de saint Eucher, qui aurait vu Charles Martel brûler en enfer pour avoir distribué des biens d'Église. On voit combien ces terres ont fâché le clergé.","Les chroniqueurs arabes appellent le lieu de la bataille « la chaussée des martyrs », car Abd al-Rahman et beaucoup de ses hommes y sont tombés.","Le chêne de Geismar : Boniface l'aurait fait abattre et en aurait utilisé le bois pour bâtir une chapelle. Un geste de défi, selon la tradition, face aux croyances germaniques."] },
      items: [
        { type: "qcm", q: "Qui est le père de Charles Martel ?", c: "Pépin de Herstal", w: ["Pépin le Bref", "Dagobert Ier", "Thierry IV"], e: "Pépin de Herstal, maire du palais, est vainqueur à Tertry. Pépin le Bref, au contraire, est le fils de Charles Martel." },
        { type: "qcm", q: "Que signifie le surnom « Martel », donné plus tard à Charles ?", c: "Marteau", w: ["Bouclier", "Lance", "Faucon"], e: "Le surnom n'apparaît que bien après sa mort. Il évoque un chef qui écrase ses adversaires comme un marteau." },
        { type: "qcm", q: "Quel gouverneur d'al-Andalus commande l'armée musulmane vaincue près de Poitiers ?", c: "Abd al-Rahman", w: ["Tariq ibn Ziyad", "Musa ibn Nusayr", "Yusuf al-Fihri"], e: "Abd al-Rahman al-Ghafiqi est tué pendant la bataille. Tariq et Musa avaient conduit, vingt ans plus tôt, la conquête de l'Espagne wisigothique." },
        { type: "qcm", q: "Quel missionnaire anglo-saxon, surnommé l'apôtre de la Germanie, est protégé par Charles Martel ?", c: "Boniface", w: ["Colomban", "Augustin de Cantorbéry", "Martin de Tours"], e: "Boniface fonde des évêchés et des monastères en Germanie, comme Fulda. Il meurt martyr chez les Frisons en 754." },
        { type: "qcm", q: "Quel duc d'Aquitaine, d'abord adversaire de Charles, demande son aide face aux armées musulmanes ?", c: "Eudes", w: ["Waïfre", "Hunald", "Gondebaud"], e: "Eudes, battu près de Bordeaux, se tourne vers son rival franc. Son fils Hunald et son petit-fils Waïfre lutteront ensuite contre les Francs." },
        { type: "tf", q: "Charles Martel n'a jamais porté le titre de roi des Francs.", a: true, e: "Il gouverne comme maire du palais. Ce sont son fils Pépin et sa famille qui franchiront le pas, en 751." },
        { type: "tf", q: "À la mort de Pépin de Herstal en 714, son fils Charles est aussitôt reconnu maire du palais sans opposition.", a: false, e: "Plectrude le fait emprisonner pour garder le pouvoir. Charles s'évade et doit conquérir sa place par les armes, jusqu'à la victoire de Vinchy en 717." },
        { type: "order", q: "Remets ces événements autour de Charles Martel dans l'ordre chronologique.", items: [{ t: "Victoire de Charles à Vinchy", y: "717" }, { t: "Le pape envoie Boniface en Germanie", y: "719" }, { t: "Mort du roi Thierry IV, trône vacant", y: "737" }, { t: "Mort de Charles Martel", y: "741" }] },
        { type: "match", q: "Associe chaque mot de vocabulaire à sa définition.", pairs: [["Maire du palais", "Chef de la maison du roi"], ["Bénéfice", "Terre confiée en échange d'un service"], ["Vassal", "Homme lié par serment à un chef"], ["Duc", "Chef d'une grande province"]] },
        { type: "year", q: "En quelle année Charles Martel arrête l'armée musulmane près de Poitiers ?", y: 732, min: 680, max: 820, tol: 2, e: "On date la bataille de 732, parfois de 733 : les chroniques ne sont pas assez précises. Les historiens la voient aujourd'hui comme un épisode important, mais non comme un choc de civilisations." }
      ]
    },
    {
      title: "Pépin le Bref prend la couronne",
      lesson: { d: "741 – 768", t: "Pépin le Bref, un maire devenu roi", hook: "Peut-on devenir roi parce qu'on gouverne déjà ? Pépin pose la question au pape, et la réponse change la couronne des Francs pour des siècles.", p: "À la mort de Charles Martel, ses deux fils Carloman et Pépin se partagent le pouvoir. Ils ont fort à faire : les Aquitains, les Bavarois, les Alamans se révoltent, et leur demi-frère Grifon aussi. Pour calmer les esprits, ils placent sur le trône un roi mérovingien, Childéric III. En 747, Carloman, las du pouvoir, entre au monastère et laisse Pépin seul. Les gens l'appellent « le Bref », c'est-à-dire « le petit », sans doute à cause de sa taille.\n\n## Une question pour le pape\n\nPépin est le maître, mais il n'est pas roi. Il envoie à Rome deux hommes de confiance, l'abbé Fulrad de Saint-Denis et l'évêque Burchard de Wurtzbourg, poser une question au pape Zacharie : vaut-il mieux appeler roi celui qui n'a plus que le titre, ou celui qui détient le pouvoir ? La réponse du pape est favorable à Pépin. Le Franc réunit alors les grands, qui l'élisent roi, au milieu du VIIIe siècle. Childéric III est tondu, signe qu'il perd la royauté, et enfermé dans un monastère. Le dernier roi aux cheveux longs n'est plus.\n\nPépin sait qu'un coup d'État, même appuyé par les grands, reste fragile. Il lui faut une légitimité sacrée. Il reçoit l'onction, une huile bénie qui rappelle celle des rois de l'Ancien Testament, comme David. Roi par l'élection, il devient roi « par la grâce de Dieu ».\n\n## Un pape traverse les Alpes\n\nLe pape Étienne II, lui, a besoin d'un protecteur : les Lombards du roi Aistolf ont pris Ravenne et menacent Rome, et l'empereur de Byzance ne vient pas. En plein hiver, le pape franchit les Alpes, un fait exceptionnel, et rencontre Pépin à Ponthion, en Champagne, en janvier 754. Il passe l'hiver à Saint-Denis, où il consacre de nouveau Pépin, sa femme Bertrade et leurs fils Charles et Carloman. Il leur donne le titre de patrice des Romains, c'est-à-dire de protecteur de Rome.\n\nEn échange, Pépin passe deux fois les Alpes, en 755 et en 756. Il bat Aistolf et assiège Pavie. Les villes conquises, dont Ravenne, sont offertes non à l'empereur de Byzance, comme celui-ci l'espérait, mais « à saint Pierre », c'est-à-dire au pape. C'est le noyau des futurs États pontificaux, qui dureront jusqu'au XIXe siècle. La papauté et les Francs sont désormais liés.\n\n## Narbonne, l'Aquitaine et Saint-Denis\n\nPépin a aussi des ennemis plus proches. En 759, après des années de siège, il prend Narbonne aux musulmans : leur dernier point d'appui au nord des Pyrénées disparaît. Il combat ensuite en Aquitaine contre le duc Waïfre, qui est tué en 768. Malade, Pépin meurt la même année à Saint-Denis et partage le royaume entre ses fils Charles et Carloman. Le premier sera Charlemagne. L'abbaye de Saint-Denis, où repose Pépin, deviendra la nécropole des rois de France.", fun: ["En 757, l'empereur de Byzance envoie à Pépin le Bref un orgue, instrument alors inconnu des Francs. Les cours se courtisent à coups de cadeaux.","Le moine Notker raconte, un siècle plus tard, que Pépin aurait un jour tranché d'un coup la tête d'un lion qui attaquait un taureau, pour faire taire ceux qui se moquaient de sa taille. Une belle légende, pas un fait établi.","Bertrade, épouse de Pépin et mère de Charlemagne, est devenue « Berthe au grand pied » dans les romans médiévaux, un surnom que l'histoire ne confirme pas."] },
      items: [
        { type: "qcm", q: "Quel est le dernier roi mérovingien, déposé par Pépin le Bref ?", c: "Childéric III", w: ["Dagobert III", "Thierry IV", "Clotaire IV"], e: "Childéric III est tondu, signe de la perte de la royauté, puis enfermé dans un monastère. Il y meurt quelques années plus tard." },
        { type: "qcm", q: "Quel pape sacre Pépin à Saint-Denis et lui demande de l'aide contre les Lombards ?", c: "Étienne II", w: ["Léon III", "Adrien Ier", "Grégoire le Grand"], e: "Étienne II franchit les Alpes en plein hiver pour rencontrer Pépin, ce qui est exceptionnel : un pape vient lui-même demander l'aide d'un roi franc." },
        { type: "qcm", q: "À qui Pépin remet-il les territoires pris au roi lombard Aistolf ?", c: "Au pape", w: ["À l'empereur de Byzance", "Au duc de Bavière", "À son frère Carloman"], e: "Cette donation, vers 756, est à l'origine des États pontificaux. Elle lie durablement la papauté et la dynastie carolingienne." },
        { type: "qcm", q: "Quelle grande ville de Septimanie, aux mains des musulmans depuis 719, Pépin reprend-il ?", c: "Narbonne", w: ["Toulouse", "Marseille", "Bordeaux"], e: "Après plusieurs années de siège, Narbonne passe aux Francs en 759. Les musulmans perdent leur dernier point d'appui au nord des Pyrénées." },
        { type: "qcm", q: "Quel frère de Pépin se retire dans un monastère en 747 ?", c: "Carloman", w: ["Grifon", "Drogon", "Childebrand"], e: "Carloman part pour l'Italie, puis pour l'abbaye du Mont-Cassin. Son retrait fait de Pépin le seul maître du royaume franc." },
        { type: "tf", q: "En 754, le pape sacre non seulement Pépin, mais aussi ses fils Charles et Carloman.", a: true, e: "L'onction est donnée à toute la famille, ce qui fonde l'hérédité de la dynastie nouvelle et la place sous la protection de l'Église." },
        { type: "tf", q: "Pour devenir roi, Pépin s'appuie sur l'accord de l'empereur de Byzance.", a: false, e: "Pépin cherche l'appui du pape Zacharie, puis d'Étienne II. Byzance, lointaine et affaiblie en Italie, n'intervient pas." },
        { type: "order", q: "Remets ces événements sous Pépin le Bref dans l'ordre chronologique.", items: [{ t: "Carloman devient moine", y: "747" }, { t: "Sacre de Pépin par Étienne II à Saint-Denis", y: "754" }, { t: "Prise de Narbonne", y: "759" }, { t: "Mort de Pépin le Bref", y: "768" }] },
        { type: "match", q: "Associe chaque lieu à son rôle dans l'histoire de Pépin.", pairs: [["Rome", "Résidence du pape Zacharie"], ["Saint-Denis", "Abbaye du sacre de 754"], ["Pavie", "Capitale du royaume lombard"], ["Ravenne", "Capitale de l'exarchat, cédée au pape"]] },
        { type: "year", q: "En quelle année Pépin le Bref est-il élu roi des Francs ?", y: 751, min: 700, max: 820, tol: 1, e: "En 751, Pépin devient roi et fonde la dynastie carolingienne. Le nom vient de Carolus, nom latin de Charles Martel et de Charlemagne." }
      ]
    },
    {
      title: "Charlemagne en guerre",
      lesson: { d: "768 – 804", t: "Charlemagne, roi conquérant", hook: "Presque chaque été, il monte à cheval et part en campagne. En quarante ans, Charles étend le royaume des Francs de l'Italie à la Saxe, et l'histoire n'oubliera pas son nom.", p: "Charles, fils de Pépin le Bref et de Bertrade, naît vers 747. Il devient roi des Francs en 768, avec son frère Carloman, puis seul quelques années plus tard, à la mort de celui-ci. Éginhard le décrit grand, avec une tête ronde, de grands yeux vifs et une voix un peu plus aiguë qu'on ne l'attendrait. Il mesurait, dit-il, sept fois la longueur de son pied. Il s'habille à la mode franque, aime la chasse, et passe plus de temps à cheval qu'au palais.\n\n## L'Italie : un roi à Pavie\n\nEn Italie, le roi lombard Didier menace le pape Adrien Ier, qui appelle Charles au secours. Charles franchit les Alpes et assiège Pavie, la capitale lombarde. Pendant le siège, il se rend à Rome pour Pâques. La ville finit par tomber, Didier est envoyé finir ses jours au monastère, et Charles prend le titre de roi des Francs et des Lombards, en plus de celui de patrice des Romains. Il n'y a plus de royaume lombard indépendant.\n\n## Roncevaux, la défaite qui devient légende\n\nEn 778, Charles part pour l'Espagne, à l'appel de gouverneurs musulmans révoltés contre l'émir de Cordoue. L'expédition tourne court devant Saragosse. Au retour, il détruit les remparts de Pampelune. Le 15 août, dans les Pyrénées, son arrière-garde est surprise dans un défilé par des montagnards basques, qui emportent le butin. Éginhard cite parmi les morts un certain Roland, chef de la marche de Bretagne.\n\nDe cette petite défaite, on fera un grand poème. La Chanson de Roland, écrite vers l'an 1100, change les Basques en Sarrasins, donne à Roland une épée nommée Durandal et un cor, l'olifant. Une embuscade de montagne est devenue un combat entre deux mondes.\n\n## Trente ans contre les Saxons\n\nLa guerre la plus longue est celle contre les Saxons, païens de Germanie du Nord, qui n'ont pas de roi mais des chefs de clans. En 772, Charles détruit leur pilier sacré, l'Irminsul. Leur chef Widukind mène la résistance et, en 782, il écrase une armée franque au mont Süntel. Charles réplique par le massacre de Verden : selon les Annales royales, plusieurs milliers de Saxons sont exécutés. Une loi punit de mort ceux qui refusent le baptême. Même Alcuin, proche conseiller du roi, avertit que la foi ne peut pas s'imposer par la force. Widukind se soumet et se fait baptiser vers 785, mais la guerre dure jusqu'en 804, avec des déportations. Des évêchés sont fondés, comme Brême ou Paderborn.\n\n## Bavière et Avars : les derniers adversaires\n\nCharles élimine aussi les rivaux internes : en 788, il dépose son cousin Tassilon, duc de Bavière, qui finit dans un monastère. Puis il se tourne vers les Avars, cavaliers installés sur le Danube. En 795-796, son fils Pépin d'Italie et le duc Éric du Frioul prennent leur camp fortifié, le Ring, et en rapportent un énorme trésor, dont une part est offerte au pape. À la fin de ces campagnes, l'empire s'étend des Pyrénées au Danube et du nord de l'Italie à la Saxe.", fun: ["En 793, Charlemagne tente de relier le Rhin au Danube en creusant un canal entre deux petites rivières, la Fossa Carolina. Les pluies font échouer le chantier, mais on en voit encore des traces en Bavière.","Dans la Chanson de Roland, le cor de Roland sonne si fort qu'on l'entend à plusieurs lieues et que sa bouche saigne. Dans l'histoire, il n'y a ni olifant ni Durandal.","Selon Éginhard, les médecins voulaient que Charlemagne mange du bouilli plutôt que du rôti, son plat préféré. Il n'aimait pas du tout qu'on lui dise quoi manger."] },
      items: [
        { type: "qcm", q: "Quel roi lombard, dont Charlemagne avait épousé puis répudié la fille, est finalement vaincu ?", c: "Didier", w: ["Aistolf", "Liutprand", "Alboin"], e: "Didier est envoyé finir ses jours dans un monastère. Charles prend le titre de roi des Lombards." },
        { type: "qcm", q: "Quelle ville, capitale du royaume lombard, résiste à un long siège de Charlemagne avant de se rendre ?", c: "Pavie", w: ["Milan", "Vérone", "Florence"], e: "Le siège dure environ neuf mois. Charles y gagne l'Italie du Nord, dont il se proclame roi." },
        { type: "qcm", q: "Quel chef saxon résiste le plus longtemps à Charlemagne ?", c: "Widukind", w: ["Arminius", "Tassilon", "Radbod"], e: "Widukind finit par se soumettre et se faire baptiser, vers 785. Arminius, lui, est un chef germain du Ier siècle, ennemi de Rome." },
        { type: "qcm", q: "Qui attaque l'arrière-garde de Charlemagne à Roncevaux ?", c: "Des Basques", w: ["Des Sarrasins", "Des Saxons", "Des Lombards"], e: "Les chroniques franques parlent d'une embuscade de montagnards basques, attirés par le butin. C'est la légende qui en fera plus tard des musulmans." },
        { type: "qcm", q: "Quel peuple de cavaliers installé près du Danube voit son trésor pillé par les Francs ?", c: "Les Avars", w: ["Les Huns", "Les Hongrois", "Les Bulgares"], e: "Le « Ring » des Avars, leur camp fortifié, est pillé en 795-796. Les Huns d'Attila appartenaient à une époque bien plus ancienne." },
        { type: "tf", q: "La conquête de la Saxe dure moins de cinq ans.", a: false, e: "Elle dure plus de trente ans, de 772 à 804. Charles y fonde des évêchés et y impose le christianisme par la force." },
        { type: "tf", q: "Selon les Annales royales, Charlemagne fait exécuter plusieurs milliers de Saxons à Verden en 782.", a: true, e: "Le chiffre de 4 500 victimes est traditionnel. Les historiens le discutent, mais s'accordent sur un massacre massif." },
        { type: "order", q: "Remets ces événements pendant les conquêtes de Charlemagne dans l'ordre chronologique.", items: [{ t: "Charles devient roi des Francs", y: "768" }, { t: "Pavie tombe, Charles roi des Lombards", y: "774" }, { t: "Embuscade de Roncevaux", y: "778" }, { t: "Massacre de Verden", y: "782" }] },
        { type: "match", q: "Associe chaque peuple à sa région.", pairs: [["Lombards", "Italie du Nord"], ["Saxons", "Germanie du Nord"], ["Avars", "Plaine du Danube"], ["Bavarois", "Duché de Tassilon"]] },
        { type: "year", q: "En quelle année Charlemagne devient-il seul roi des Francs, à la mort de son frère Carloman ?", y: 771, min: 730, max: 850, tol: 1, e: "Carloman meurt en décembre 771. Sa veuve et ses fils s'enfuient chez le roi lombard Didier, ce qui précipitera la guerre en Italie." }
      ]
    },
    {
      title: "Noël 800 : un empereur à Rome",
      lesson: { d: "799 – 814", t: "L'empereur de Noël et la cour d'Aix", hook: "C'est la messe de Noël à Rome. Le roi des Francs prie à genoux dans la basilique Saint-Pierre quand le pape s'approche avec une couronne. Que va-t-il se passer ?", p: "En 799, le pape Léon III est agressé en pleine procession par des adversaires romains. Il s'échappe et vient chercher refuge auprès de Charlemagne, en Germanie. L'année suivante, le roi se rend à Rome, fait examiner les accusations contre le pape, et le pape se disculpe par serment. Quelques jours plus tard, c'est Noël.\n\n## Noël 800, la couronne et la foule\n\nDans la basilique Saint-Pierre, le pape pose une couronne sur la tête de Charles tandis que la foule crie : « À Charles Auguste, couronné par Dieu, grand et pacifique empereur des Romains, vie et victoire ! » Un empereur d'Occident : il n'y en avait plus depuis le Ve siècle. Selon Éginhard, Charles aurait été contrarié et aurait dit qu'il ne serait pas entré dans l'église ce jour-là s'il avait su. Les historiens se demandent si ce n'était pas de la modestie de façade.\n\nÀ Byzance, on n'apprécie pas du tout. Pour les Byzantins, il ne peut y avoir qu'un seul empereur des Romains, le leur. L'impératrice Irène règne alors à Constantinople, et certains, en Occident, soutiennent même que le trône impérial est vacant puisqu'une femme l'occupe. Il faut attendre 812 pour que Byzance reconnaisse le titre de Charles.\n\n## Aix-la-Chapelle, capitale d'un rêve\n\nCharlemagne n'a pas de capitale fixe, mais il aime Aix-la-Chapelle, pour ses sources chaudes. Il y construit un palais et une chapelle à plan octogonal, souvent comparée à l'église Saint-Vital de Ravenne. Marbres et colonnes sont rapportés d'Italie, avec l'accord du pape. La tradition place la consécration de la chapelle en 805. On y voit encore le trône de marbre, accessible par six marches. Éginhard raconte que le roi adore nager dans les thermes et y invite parfois des dizaines de personnes en même temps.\n\nAix reçoit aussi des visiteurs venus de loin. Le calife de Bagdad Haroun al-Rachid envoie à Charlemagne un éléphant nommé Abul-Abbas, qui fait le voyage avec un émissaire du roi, Isaac, à travers l'Afrique du Nord et l'Italie. Il arrive en 802, et la cour reste bouche bée. L'éléphant vivra à Aix jusqu'en 810.\n\n## La fin du règne\n\nCharlemagne meurt à Aix en janvier, vers l'âge de soixante-dix ans, après plus de quarante ans de règne. Son fils Louis, qu'il a lui-même couronné, lui succède : ses fils aînés étaient morts avant lui. Il est enterré dans sa chapelle. Au XIIe siècle, l'empereur Frédéric Barberousse fait canoniser Charlemagne par un antipape, et ses reliques sont placées dans une châsse d'or. Pendant plus de six siècles, des rois des Romains seront couronnés dans cette même ville. Visiter la cathédrale d'Aix aujourd'hui, c'est entrer dans le monde de Charlemagne.", fun: ["Selon une légende, l'empereur Otton III aurait fait ouvrir le tombeau de Charlemagne en l'an 1000 et l'aurait trouvé assis sur un trône, couronne sur la tête. Un récit pittoresque, mais tardif.","En 1165, Frédéric Barberousse obtient que Charlemagne soit déclaré saint. Mais l'antipape qui prononce cette canonisation n'est pas reconnu par Rome : le culte de Charlemagne reste local.","Selon les Annales royales, l'éléphant Abul-Abbas meurt en 810, pendant une expédition contre les Danois. La cour a pleuré le plus célèbre pensionnaire d'Aix."] },
      items: [
        { type: "qcm", q: "Dans quelle basilique Charlemagne reçoit-il la couronne impériale ?", c: "Saint-Pierre de Rome", w: ["Saint-Jean-de-Latran", "Sainte-Sophie", "Saint-Denis"], e: "La basilique Saint-Pierre abrite le tombeau de l'apôtre. Le choix du lieu souligne le lien entre le nouvel empereur et la papauté." },
        { type: "qcm", q: "Quel animal exotique le calife Haroun al-Rachid offre-t-il à Charlemagne ?", c: "Un éléphant", w: ["Un lion", "Une girafe", "Un dromadaire"], e: "Abul-Abbas voyage d'Afrique du Nord jusqu'à Aix, où il vit jusqu'en 810. Le cadeau montre que les deux puissances échangeaient des ambassades." },
        { type: "qcm", q: "Quel empire se considère toujours, après 800, comme le seul héritier de Rome ?", c: "L'Empire byzantin", w: ["Le califat abbasside", "L'Empire bulgare", "Le royaume des Asturies"], e: "Pour Byzance, il ne peut y avoir qu'un empereur des Romains. Le titre de Charlemagne y est vu comme une usurpation." },
        { type: "qcm", q: "Qui succède seul à Charlemagne en 814 ?", c: "Louis le Pieux", w: ["Lothaire", "Pépin d'Italie", "Charles le Jeune"], e: "Ses fils aînés Pépin et Charles étaient morts en 810 et 811. Louis, roi d'Aquitaine, reste seul héritier." },
        { type: "qcm", q: "Quel lettré, secrétaire de Charlemagne, écrit sa Vie ?", c: "Éginhard", w: ["Alcuin", "Paul Diacre", "Grégoire de Tours"], e: "Éginhard imite les biographies d'empereurs romains. Il décrit un souverain grand, à la voix un peu aiguë, qui aimait nager." },
        { type: "tf", q: "Selon Éginhard, Charlemagne aurait été surpris par son couronnement impérial.", a: true, e: "Éginhard écrit que l'empereur n'aurait pas mis les pieds à l'église ce jour-là s'il avait connu les intentions du pape. Les historiens discutent la sincérité de ce passage." },
        { type: "tf", q: "Charlemagne est enterré à l'abbaye de Saint-Denis.", a: false, e: "Il est inhumé à Aix-la-Chapelle, dans la chapelle qu'il avait fait bâtir. Saint-Denis accueille Pépin le Bref, son père." },
        { type: "order", q: "Remets ces événements autour du couronnement de 800 dans l'ordre chronologique.", items: [{ t: "Le pape Léon III se réfugie auprès de Charles", y: "799" }, { t: "Couronnement impérial à Rome", y: "800" }, { t: "Arrivée de l'éléphant Abul-Abbas à Aix", y: "802" }, { t: "Byzance reconnaît le titre impérial", y: "812" }] },
        { type: "match", q: "Associe chaque acteur de l'an 800 à son rôle.", pairs: [["Léon III", "Pape qui couronne l'empereur"], ["Haroun al-Rachid", "Calife de Bagdad"], ["Irène", "Impératrice de Byzance"], ["Aix-la-Chapelle", "Palais, chapelle et thermes"]] },
        { type: "year", q: "En quelle année meurt Charlemagne ?", y: 814, min: 760, max: 900, tol: 1, e: "Il meurt le 28 janvier 814, vers soixante-dix ans. Son fils Louis le Pieux lui succède sans difficulté." }
      ]
    },
    {
      title: "Alcuin et la renaissance des lettres",
      lesson: { d: "781 – vers 830", t: "Alcuin, les écoles et la minuscule caroline", hook: "Tu lis ces lignes avec des lettres minuscules bien séparées ? Tu le dois en partie à des moines de l'époque de Charlemagne, qui ont inventé une écriture plus lisible que toutes les autres.", p: "Charlemagne sait parler le francique, comprend le latin et un peu le grec, mais écrit mal. Éginhard raconte qu'il garde des tablettes sous son oreiller pour s'exercer, sans grand succès. Il veut pourtant des évêques et des fonctionnaires qui lisent. Pour y parvenir, il cherche les meilleurs savants d'Europe, et en 781, à Parme, il rencontre Alcuin, un lettré venu d'York, en Angleterre.\n\n## Le savant venu d'York\n\nAlcuin dirige l'école du palais. Autour de lui se forme un cercle : l'Italien Pierre de Pise, le Lombard Paul Diacre, historien de son peuple, Théodulf d'origine wisigothique, et plus tard Éginhard. Ils s'amusent à se donner des surnoms : le roi est David, Alcuin est Flaccus, comme le poète latin Horace. Alcuin donne aussi des cours au roi et à sa famille, sur la grammaire, l'astronomie, la rhétorique. On lui attribue même un recueil de devinettes mathématiques, dont le célèbre problème du loup, de la chèvre et du chou à faire passer sur l'autre rive d'une rivière.\n\n## Une école dans chaque évêché\n\nÀ la fin des années 780, un texte royal, l'Admonitio generalis, demande que chaque évêché et chaque monastère ouvre une école où l'on apprend à lire, à chanter et à compter. Il réclame aussi des livres corrects et un chant uniforme dans les églises. Les clercs étudient le trivium (grammaire, rhétorique, dialectique), puis le quadrivium (arithmétique, géométrie, astronomie, musique). Ces écoles sont destinées à former des prêtres, pas tout le monde : la plupart des gens ne savent pas lire.\n\n## Les moines copistes\n\nLes vrais héros de cette renaissance sont les moines des scriptoria. Du matin au soir, dans un silence qu'interrompt seulement le grincement des plumes, ils recopient sur du parchemin la Bible, les Pères de l'Église et de nombreux auteurs latins de l'Antiquité. Une grande Bible demande les peaux de centaines d'animaux. Les plus beaux livres, comme l'Évangéliaire de Godescalc, sont ornés d'enluminures et écrits en lettres d'or sur du parchemin teint en pourpre.\n\nPour que les textes soient lisibles, on met au point une écriture claire et aérée : la minuscule caroline. Les mots sont séparés par des espaces, les lettres sont rondes et distinctes, les majuscules et les minuscules se distinguent. Quand, au XVe siècle, les humanistes italiens cherchent un modèle d'écriture, ils croient imiter l'Antiquité alors qu'ils copient en réalité cette écriture carolingienne, et c'est elle qui inspire les caractères d'imprimerie que nous lisons.\n\nAlcuin devient en 796 abbé de Saint-Martin de Tours, dont l'atelier produit de superbes Bibles, et meurt en 804. Théodulf, devenu évêque d'Orléans, fait décorer son oratoire de Germigny-des-Prés d'une mosaïque qu'on peut encore admirer. Vers 820-830, on dessine le plan idéal d'une abbaye, conservé à Saint-Gall : on y voit une église, un cloître, une infirmerie, une école, un jardin et même une brasserie. Beaucoup d'œuvres antiques ne nous sont connues que parce qu'un copiste carolingien les a recopiées.", fun: ["Le problème du loup, de la chèvre et du chou, que l'on raconte encore aux enfants, figure déjà dans un recueil de devinettes que la tradition attribue à Alcuin. Il a plus de mille deux cents ans.","Les mots « majuscule » et « minuscule » viennent du latin : maiusculus et minusculus, « un peu plus grand » et « un peu plus petit ». La distinction systématique entre les deux se répand à l'époque carolingienne.","Le plan de Saint-Gall n'a jamais été construit tel quel : c'est un projet idéal dessiné sur cinq peaux de parchemin cousues ensemble, avec des légendes pour chaque bâtiment."] },
      items: [
        { type: "qcm", q: "De quel pays vient Alcuin, le principal animateur de l'école du palais de Charlemagne ?", c: "D'Angleterre", w: ["D'Irlande", "D'Italie", "D'Espagne"], e: "Alcuin a été formé à l'école cathédrale d'York. Les monastères anglo-saxons étaient alors parmi les meilleurs centres d'étude d'Europe." },
        { type: "qcm", q: "Quelle abbaye Alcuin dirige-t-il à partir de 796 ?", c: "Saint-Martin de Tours", w: ["Saint-Denis", "Fulda", "Saint-Gall"], e: "À Tours, le scriptorium copie des Bibles complètes, dont plusieurs exemplaires luxueux. Alcuin y meurt en 804." },
        { type: "qcm", q: "Comment appelle-t-on l'ensemble arithmétique, géométrie, astronomie et musique, enseigné après le trivium ?", c: "Le quadrivium", w: ["Le scriptorium", "Le florilège", "Le capitulaire"], e: "Trivium et quadrivium forment les sept arts libéraux, base des études médiévales pendant des siècles." },
        { type: "qcm", q: "Quel texte de 789 demande l'ouverture d'écoles auprès des évêchés et des monastères ?", c: "L'Admonitio generalis", w: ["Le Code théodosien", "La Règle de saint Benoît", "Le Pactus legis Salicae"], e: "Ce capitulaire compte plus de quatre-vingts articles. Il réclame aussi des textes bien corrigés et un chant liturgique uniforme." },
        { type: "qcm", q: "Quel évêque d'Orléans, d'origine wisigothique, est aussi poète à la cour de Charlemagne ?", c: "Théodulf", w: ["Hincmar", "Agobard", "Raban Maur"], e: "Théodulf fait aussi décorer son oratoire de Germigny-des-Prés d'une belle mosaïque, que l'on peut voir encore aujourd'hui." },
        { type: "tf", q: "Grâce aux copistes carolingiens, de nombreuses œuvres latines de l'Antiquité nous sont parvenues.", a: true, e: "Beaucoup de textes antiques ne survivent que dans des copies carolingiennes, recopiées ensuite pendant tout le Moyen Âge." },
        { type: "tf", q: "À l'époque de Charlemagne, la majorité de la population sait lire et écrire.", a: false, e: "Savoir lire reste rare : surtout les clercs, quelques grands laïcs. Les écoles voulues par Charlemagne visent d'abord à former des prêtres." },
        { type: "order", q: "Remets ces événements de la renaissance carolingienne dans l'ordre chronologique.", items: [{ t: "Alcuin rencontre Charlemagne à Parme", y: "781" }, { t: "Alcuin devient abbé de Saint-Martin de Tours", y: "796" }, { t: "Mort d'Alcuin", y: "804" }, { t: "Plan idéal de l'abbaye de Saint-Gall", y: "vers 820-830" }] },
        { type: "match", q: "Associe chaque terme à sa définition.", pairs: [["Scriptorium", "Atelier de copie des manuscrits"], ["Caroline", "Écriture claire et lisible"], ["Parchemin", "Peau préparée pour écrire"], ["Enluminure", "Image peinte dans un manuscrit"]] },
        { type: "year", q: "En quelle année est publiée l'Admonitio generalis, qui réclame des écoles dans tout le royaume ?", y: 789, min: 740, max: 880, tol: 1, e: "Charlemagne y exige que les enfants soient instruits. Son objectif n'est pas d'instruire tout le monde, mais d'avoir des prêtres et des fonctionnaires capables." }
      ]
    },
    {
      title: "Gouverner l'empire, vivre à la villa",
      lesson: { d: "779 – 813", t: "Gouverner un empire : comtes, missi, villa", hook: "Pas d'e-mail, pas de routes sûres, pas de police : comment un empereur peut-il se faire obéir à des semaines de cheval ? Charlemagne a trouvé quelques astuces, et elles ont survécu jusqu'à nous.", p: "Un message envoyé d'Aix-la-Chapelle met des semaines à atteindre la Septimanie. Et pourtant, il faut lever des armées, rendre la justice et percevoir des revenus. Charlemagne gouverne d'abord par des hommes de confiance : les comtes, qui représentent le roi dans chaque comté, rendent la justice et lèvent les hommes pour l'armée, et les marquis, qui commandent sur les frontières, appelées marches. La marche d'Espagne, autour de Barcelone, en est une.\n\n## Le champ de mai et les capitulaires\n\nChaque printemps, les grands se réunissent auprès du roi à l'assemblée appelée le champ de mai. Elle a d'abord lieu en mars ; c'est Pépin le Bref qui l'avait déplacée en mai. On y discute des lois et surtout de la guerre de l'année. Les décisions du roi sont écrites en latin, dans des textes divisés en petits articles, les capitula : d'où leur nom de capitulaires. On y trouve de tout : des règles de justice, de monnaie, de religion, d'école.\n\nPour s'assurer que ses ordres sont suivis, Charlemagne multiplie les missi dominici, les « envoyés du maître », qui parcourent les comtés par deux, souvent un clerc et un laïc, pour contrôler les comtes et écouter les plaintes. À la même époque, il fait prêter serment de fidélité à tous les hommes libres, et il ordonne une réforme de la monnaie : le denier d'argent devient la monnaie de base.\n\n## Dans la villa, avec les paysans\n\nPour la plupart des gens, la vie se passe dans la villa, un grand domaine agricole. Le maître, roi, évêque ou abbé, y possède une réserve, qu'on cultive pour lui grâce aux corvées des paysans, c'est-à-dire des jours de travail gratuits. Le reste est divisé en manses, des terres confiées à des familles qui versent aussi des redevances en nature. Un registre de terres et de paysans s'appelle un polyptyque ; celui de l'abbé Irminon, pour Saint-Germain-des-Prés, est resté célèbre.\n\nVers l'an 800, le Capitulaire de villis donne aux intendants des domaines royaux des consignes très précises : tenir des comptes, soigner les animaux, vendre les surplus d'œufs et de volaille, et cultiver dans les jardins des dizaines de plantes, comme la sauge, le fenouil ou l'ail. Le roi s'inquiète même de la façon de faire le vin, et défend qu'on foule le raisin aux pieds.\n\nOn mange surtout du pain, des bouillies de céréales, des légumes, un peu de fromage et de porc ; on boit de la cervoise, de la bière d'orge, et du vin dans les régions de vigne. Les maisons sont en bois et en terre, les villes sont petites, mais les moulins à eau se multiplient dans les campagnes.\n\n## Sou, livre, denier : des mots qui durent\n\nLa réforme monétaire de la fin du VIIIe siècle a une descendance incroyable. Douze deniers font un sou, vingt sous une livre : ces deux derniers ne sont que des unités de compte, seul le denier est une vraie pièce. Ce système a duré jusqu'au XVIIIe siècle en France. En 806, Charlemagne prévoit de partager l'empire entre trois fils ; la mort de deux d'entre eux change tout, et en 813 il fait couronner Louis à Aix, à ses côtés.", fun: ["En Angleterre, la livre sterling, le shilling et le penny s'écrivaient £, s et d. Le « d » vient de denarius, le denier, et le « s » de solidus, le sou : un héritage du système monétaire carolingien.","Le Capitulaire de villis demande qu'on cultive plus de soixante-dix plantes, parmi lesquelles des lis et des roses, que l'on trouve dans nos jardins d'agrément.","Les missi dominici partent par deux, souvent un évêque et un comte, pour que chacun surveille l'autre. Une façon ingénieuse d'éviter la corruption."] },
      items: [
        { type: "qcm", q: "Comment nomme-t-on l'assemblée annuelle où les grands se réunissent au printemps auprès du roi ?", c: "Le champ de mai", w: ["Les états généraux", "Le concile œcuménique", "La diète de Worms"], e: "On y décide des guerres de l'année et on y discute des lois. Les guerriers s'y rassemblent avant de partir en campagne." },
        { type: "qcm", q: "Quel texte, vers 800, donne des consignes pour la gestion des domaines royaux et la culture des plantes ?", c: "Le Capitulaire de villis", w: ["La loi salique", "Le polyptyque d'Irminon", "La Règle de saint Benoît"], e: "Il liste plus de soixante-dix plantes à cultiver dans les jardins, comme la sauge, le fenouil ou l'ail, et demande de tenir des comptes précis." },
        { type: "qcm", q: "Dans une villa, comment s'appelle la partie du domaine cultivée directement pour le maître ?", c: "La réserve", w: ["La dîme", "L'alleu", "Le fief"], e: "Les paysans y travaillent par corvées. Les manses, eux, sont les terres tenues par les familles paysannes." },
        { type: "qcm", q: "Quelle pièce d'argent est la monnaie de base de l'empire carolingien ?", c: "Le denier", w: ["Le florin", "Le ducat", "L'écu"], e: "Le denier d'argent remplace peu à peu l'or des Mérovingiens. Douze deniers font un sou, vingt sous une livre, mais ces deux derniers ne sont que des unités de compte." },
        { type: "qcm", q: "Comment nomme-t-on une province frontière placée sous un chef militaire, comme la « marche d'Espagne » ?", c: "Une marche", w: ["Un duché", "Un évêché", "Un manse"], e: "La marche d'Espagne, autour de Barcelone, protège la frontière sud. D'autres marches existent face aux Bretons, aux Danois ou aux Avars." },
        { type: "tf", q: "Les paysans d'une villa doivent parfois des corvées au maître du domaine.", a: true, e: "Ils doivent des journées de travail, des charrois et des redevances en nature. Ce système marque la société rurale pendant tout le Moyen Âge." },
        { type: "tf", q: "Les capitulaires de Charlemagne sont rédigés en langue germanique, jamais en latin.", a: false, e: "Ils sont écrits en latin, langue de l'administration et de l'Église. Le mot vient de capitula, les « chapitres » qui les composent." },
        { type: "order", q: "Remets ces événements du gouvernement de l'empire dans l'ordre chronologique.", items: [{ t: "Capitulaire d'Herstal", y: "779" }, { t: "Charlemagne renforce les missi dominici", y: "802" }, { t: "Partage prévu de l'empire entre trois fils", y: "806" }, { t: "Louis le Pieux couronné à Aix", y: "813" }] },
        { type: "match", q: "Associe chaque terme de la vie rurale à son sens.", pairs: [["Manse", "Tenure d'une famille paysanne"], ["Corvée", "Travail gratuit pour le maître"], ["Polyptyque", "Registre des terres et des paysans"], ["Ost", "Armée convoquée par le roi"]] },
        { type: "year", q: "En quelle année Charlemagne réunit-il un grand concile à Francfort et réforme la monnaie ?", y: 794, min: 720, max: 850, tol: 1, e: "À Francfort, en 794, on condamne aussi une doctrine sur la nature du Christ, l'adoptianisme, et on fixe des prix maximums pour les grains, en pleine période de famine." }
      ]
    },
    {
      title: "Les fils de Louis et le partage de Verdun",
      lesson: { d: "814 – 843", t: "Louis le Pieux et le partage de Verdun", hook: "Un empereur humilié en public, trois frères qui se font la guerre, un serment prononcé dans deux langues : l'empire de Charlemagne se déchire à coups de querelles de famille.", p: "Louis, seul fils légitime de Charlemagne encore vivant, devient empereur en 814. On l'appelle « le Pieux », car il est très religieux. Il soutient la réforme des monastères menée par Benoît d'Aniane, un ancien guerrier devenu moine, qui veut imposer à tous la règle de saint Benoît. Louis veut aussi organiser sa succession. En 817, il prévoit le partage de l'empire entre ses fils : Lothaire, l'aîné, devient son associé à l'empire et ses frères Pépin et Louis reçoivent des royaumes plus petits.\n\n## Un quatrième fils qui dérange tout\n\nMais Louis se remarie avec Judith de Bavière, et leur fils Charles naît en 823. Le plan de 817 ne prévoit rien pour lui. Les trois aînés se sentent menacés. Plusieurs fois, ils se révoltent contre leur père, souvent avec des grands mécontents. En 822, déjà, Louis avait accepté de faire pénitence publique à Attigny pour des fautes passées.\n\nEn 833, près de Colmar, les armées s'affrontent. Mais les soldats de Louis l'abandonnent avant de combattre : on appellera ce lieu le Champ du Mensonge. Louis est déposé et doit faire pénitence en public, les armes déposées, vêtu en pénitent. Cet épisode choque ses contemporains. L'année suivante, il retrouve le trône. Il meurt en 840, sur une île du Rhin.\n\n## Fontenoy et le serment des deux langues\n\nÀ sa mort, ses fils se battent pour l'héritage. En 841, à Fontenoy, Lothaire est vaincu par ses frères Louis et Charles. Les chroniqueurs décrivent des pertes terribles parmi l'élite franque. Les deux vainqueurs se rapprochent et, en 842, à Strasbourg, ils jurent de s'entraider contre Lothaire. Pour que chaque armée comprenne, Louis jure en langue romane, devant les soldats de Charles, et Charles jure en langue germanique, devant ceux de Louis. Puis chaque armée prête serment dans sa propre langue.\n\nLe texte nous est parvenu grâce à Nithard, petit-fils de Charlemagne par sa mère et témoin des événements, qui écrit une Histoire des fils de Louis le Pieux. Ces quelques lignes, qui commencent par « Pro Deo amur... », sont l'un des plus anciens textes en langue romane, ancêtre du français. On voit à quel point le latin n'est plus la langue de tous.\n\n## Verdun : trois parts, trois destins\n\nLes trois frères finissent par négocier à Verdun, à l'été suivant. Charles le Chauve reçoit la Francie occidentale, c'est-à-dire en gros la future France, Louis le Germanique la Francie orientale, au-delà du Rhin, et Lothaire une bande centrale qui va de la mer du Nord à l'Italie, avec Aix, Rome et le titre d'empereur. Les parts sont de valeur comparable. Mais la bande du milieu sera la plus fragile : elle sera dépecée, et son nom survit dans la Lorraine, qui vient de Lothaire II, petit-fils de Louis le Pieux (Lotharingie).\n\nLes frontières de Verdun ont longtemps marqué la séparation entre les mondes français et allemand. Elles ont aussi nourri bien des guerres, car il fallait se disputer ce que Lothaire avait laissé au milieu.", fun: ["Louis le Pieux est fait roi d'Aquitaine à trois ans, en 781. Selon un chroniqueur, on lui aurait même fait porter des armes à sa taille pour son entrée dans son royaume.","Le serment de Strasbourg est écrit dans trois langues : le texte d'introduction de Nithard est en latin, puis les serments en langue romane et en langue germanique. Deux langues futures y apparaissent côte à côte.","Le Champ du Mensonge garde ce nom parce que, selon les chroniqueurs, les promesses de fidélité faites à Louis se sont envolées avant même le combat."] },
      items: [
        { type: "qcm", q: "Quel abbé réformateur aide Louis le Pieux à imposer la règle de saint Benoît dans les monastères ?", c: "Benoît d'Aniane", w: ["Benoît de Nursie", "Bernard de Clairvaux", "Odon de Cluny"], e: "Benoît d'Aniane, un ancien guerrier devenu moine, veut qu'une seule règle gouverne tous les monastères. Benoît de Nursie en est l'auteur, au VIe siècle." },
        { type: "qcm", q: "Quelle bataille de 841 oppose Lothaire à ses deux frères, Louis et Charles ?", c: "Fontenoy", w: ["Tertry", "Vouillé", "Roncevaux"], e: "Les chroniqueurs décrivent des pertes terribles pour l'élite franque. Cette bataille ouvre la voie au partage de l'empire." },
        { type: "qcm", q: "Dans quelle langue Louis le Germanique prête-t-il le serment de Strasbourg devant les soldats de Charles ?", c: "En langue romane", w: ["En latin", "En langue germanique", "En grec"], e: "Il parle la langue que comprennent les soldats de Charles, ancêtre du français. Charles, lui, jure en langue germanique pour être compris des hommes de Louis." },
        { type: "qcm", q: "Quel petit-fils de Charlemagne rapporte le texte du serment de Strasbourg ?", c: "Nithard", w: ["Éginhard", "Hincmar", "Notker"], e: "Nithard, qui a participé à ces événements, écrit une Histoire des fils de Louis le Pieux. Il meurt peu après, en 844." },
        { type: "qcm", q: "Quelle seconde épouse de Louis le Pieux, mère de Charles le Chauve, est au cœur des querelles de succession ?", c: "Judith de Bavière", w: ["Ermengarde", "Hildegarde", "Bertrade"], e: "Ermengarde, première épouse, avait donné à Louis ses trois aînés. L'arrivée d'un quatrième fils met en péril le partage de 817." },
        { type: "tf", q: "Plusieurs fils de Louis le Pieux se révoltent contre leur père.", a: true, e: "Lothaire, Pépin et Louis se dressent contre lui, parfois ensemble. L'empereur est même humilié publiquement en 833." },
        { type: "tf", q: "Le traité de Verdun est signé avant le serment de Strasbourg.", a: false, e: "Le serment date de 842, le traité de 843. Les deux frères s'étaient alliés avant de négocier le partage avec Lothaire." },
        { type: "order", q: "Remets ces événements de Louis le Pieux et de ses fils dans l'ordre chronologique.", items: [{ t: "Ordinatio imperii, partage prévu", y: "817" }, { t: "Pénitence publique d'Attigny", y: "822" }, { t: "Champ du Mensonge", y: "833" }, { t: "Mort de Louis le Pieux", y: "840" }, { t: "Serment de Strasbourg", y: "842" }] },
        { type: "match", q: "Associe chaque souverain à sa part de l'empire.", pairs: [["Charles le Chauve", "Francie occidentale"], ["Louis le Germanique", "Francie orientale"], ["Lothaire", "Italie et bande centrale"], ["Louis le Pieux", "Empereur mort en 840"]] },
        { type: "year", q: "En quelle année le traité de Verdun partage-t-il l'empire de Charlemagne entre ses petits-fils ?", y: 843, min: 770, max: 870, tol: 1, e: "Les trois frères reçoivent des parts de valeur comparable. Les frontières de Verdun ont longtemps marqué la séparation entre les mondes français et allemand." }
      ]
    },
    {
      title: "Vikings, siège de Paris et fin d'un monde",
      lesson: { d: "793 – Xe siècle", t: "Les Vikings et la fin d'un empire", hook: "Une voile apparaît à l'horizon, puis dix, puis cent. Pour les moines et les paysans du IXe siècle, la plus grande peur vient désormais de la mer.", p: "En 793, des guerriers venus de Scandinavie attaquent le monastère de Lindisfarne, sur une île au nord-est de l'Angleterre. Ils pillent, tuent, emportent trésors et prisonniers. L'Europe chrétienne est stupéfaite. Alcuin, depuis la cour de Charlemagne, y voit un châtiment divin. Les raids vikings commencent. Les manuscrits de Lindisfarne, les célèbres Évangiles, ont survécu et sont aujourd'hui à la British Library.\n\n## Des navires qui remontent les fleuves\n\nLes Vikings sont Danois, Norvégiens, Suédois, à la fois marins, commerçants et pillards. Leurs navires longs, à fond plat, peuvent naviguer en mer, puis remonter les fleuves et même être tirés à terre pour contourner un obstacle. Ils visent les abbayes, riches et mal défendues. Du temps de Charlemagne, le roi danois Godfred défie déjà l'empire, et Charlemagne organise la défense des côtes.\n\nSous ses successeurs, la menace s'aggrave. En 845, un chef nommé Ragnar remonte la Seine avec une flotte, pille Paris et ne repart que contre une rançon en argent. Charles le Chauve apprend à payer, ce qui encourage de nouveaux raids. Il ordonne de fortifier les ponts. Dans l'ouest, le comte Robert le Fort meurt en 866 en combattant les Normands. Les rois sont trop loin ou trop faibles pour protéger tout le monde, et les populations se tournent vers les seigneurs locaux, qui bâtissent des châteaux.\n\n## Le siège de Paris\n\nEn 885, une immense flotte, avec des centaines de navires selon le moine Abbon, remonte la Seine et arrive devant Paris. La ville tient dans l'île de la Cité et commande le passage entre deux ponts. Elle est défendue par l'évêque Gozlin et le comte Eudes, fils de Robert le Fort. Pendant près d'un an, les assauts se succèdent, avec flèches, feux et machines de siège. L'évêque Gozlin meurt en cours de route, mais la ville ne tombe pas.\n\nL'empereur Charles le Gros arrive avec une armée, mais préfère traiter : il verse de l'argent aux assaillants et les laisse remonter vers la Bourgogne. Les grands le jugent indigne, et il est déposé peu après. Eudes, héros du siège, est élu roi en 888, premier roi de l'Ouest qui ne soit pas carolingien. L'empire de Charlemagne ne sera plus jamais réuni.\n\n## De Rollon à la Normandie\n\nVers 911, le roi Charles le Simple signe à Saint-Clair-sur-Epte un traité avec le chef viking Rollon : il lui laisse le pays de Rouen et la basse Seine, à charge de les défendre contre d'autres pillards. Rollon se fait baptiser et ses hommes, les Normands, s'installent peu à peu, adoptent le français et deviennent des chrétiens. Le duché de Normandie sera l'un des plus puissants du royaume. En 1066, Guillaume, un descendant de Rollon, conquiert l'Angleterre.\n\nAu Xe siècle, les rois carolingiens de France ne gardent plus qu'un pouvoir réduit, que se disputent les grandes familles. La dynastie s'éteint en 987 et laisse la place à Hugues Capet. Le monde carolingien s'est effacé, mais les Vikings ont laissé des traces dans notre langue : crique, vague, homard ou étrave viennent du norrois.", fun: ["Selon une légende racontée vers l'an 1000, Rollon aurait refusé de baiser le pied du roi. Il aurait chargé un de ses guerriers de le faire à sa place, et l'homme aurait renversé le roi en lui levant la jambe.","Le mot « drakkar » est un emprunt moderne, venu du norrois « dreki », le dragon, et n'est entré en français qu'au XIXe siècle. Les Vikings parlaient plutôt de « longs navires ».","Les mots français crique, vague, homard ou étrave viennent du norrois, la langue des Vikings, souvent par le dialecte normand. Une partie de leur héritage vit toujours dans notre vocabulaire marin."] },
      items: [
        { type: "qcm", q: "Quelle île de Northumbrie, pillée en 793, marque dans les mémoires le début des raids vikings ?", c: "Lindisfarne", w: ["Iona", "Jarrow", "Whitby"], e: "Le choc est immense : le moine Alcuin y voit un châtiment divin. Les moines y avaient copié les célèbres Évangiles de Lindisfarne." },
        { type: "qcm", q: "Quel nom français désigne couramment les navires de guerre vikings, assez légers pour remonter les fleuves ?", c: "Le drakkar", w: ["La galère", "La caraque", "La nef"], e: "Les Vikings peuvent même tirer leurs bateaux à terre pour contourner un obstacle. Le mot « drakkar » est un emprunt moderne au norrois « dreki », le dragon." },
        { type: "qcm", q: "Quel comte de Paris défend la ville en 885-886 et sera élu roi en 888 ?", c: "Eudes", w: ["Robert le Fort", "Charles le Gros", "Boson"], e: "Eudes est le premier roi non carolingien de Francie occidentale. Son père, Robert le Fort, était mort en 866 en combattant les Vikings." },
        { type: "qcm", q: "Avec quel roi carolingien Rollon traite-t-il, vers 911, à Saint-Clair-sur-Epte ?", c: "Charles le Simple", w: ["Charles le Gros", "Charles le Chauve", "Louis le Bègue"], e: "Charles le Simple confie la basse Seine à Rollon, qui doit défendre la région. Les Normands, comme on les appelle, s'intègrent peu à peu au royaume." },
        { type: "qcm", q: "Quel moine de Saint-Germain-des-Prés raconte le siège de Paris en vers ?", c: "Abbon", w: ["Flodoard", "Raoul Glaber", "Richer de Reims"], e: "Abbon, témoin du siège, décrit la tour de bois, les flèches et la défense du pont. Son poème est la source principale de l'événement." },
        { type: "tf", q: "Le traité de Saint-Clair-sur-Epte est à l'origine de la Normandie.", a: true, e: "Le nom vient de « Normands », les hommes du Nord. Le duché sera très tôt un des plus puissants du royaume." },
        { type: "tf", q: "Pendant le siège de 885-886, Paris tombe aux mains des Vikings.", a: false, e: "La ville tient bon. Les assaillants finissent par partir contre de l'argent, et le prestige du comte Eudes en sort grandi." },
        { type: "order", q: "Remets ces événements des invasions vikings dans l'ordre chronologique.", items: [{ t: "Pillage de Lindisfarne", y: "793" }, { t: "Ragnar pille Paris", y: "845" }, { t: "Siège de Paris", y: "885" }, { t: "Traité de Saint-Clair-sur-Epte", y: "911" }] },
        { type: "match", q: "Associe chaque acteur des invasions à son rôle.", pairs: [["Ragnar", "Chef viking devant Paris en 845"], ["Rollon", "Premier chef des Normands de Rouen"], ["Gozlin", "Évêque de Paris pendant le siège"], ["Godfred", "Roi danois en lutte contre Charlemagne"]] },
        { type: "year", q: "En quelle année l'empereur Charles le Gros est-il déposé ?", y: 887, min: 800, max: 940, tol: 1, e: "Malade et discrédité, il est écarté par les grands en 887 et meurt peu après. L'empire de Charlemagne ne sera plus jamais réuni." }
      ]
    }
  ],
  cast: [
    { n: "Clovis", r: "Roi des Francs, converti à Reims", d: "vers 466 – 511", b: "Roi vers quinze ans, il bat Syagrius, puis les Wisigoths, s'installe à Paris et se fait baptiser catholique. Son nom germanique, Chlodowig, a donné « Louis »." },
    { n: "Charles Martel", r: "Maire du palais, vainqueur à Poitiers", d: "vers 688 – 741", b: "Prisonnier évadé après la mort de son père, il reconstruit l'unité du royaume franc à coups de victoires. Son surnom, « le Marteau », vient plus tard. Grand-père de Charlemagne." },
    { n: "Charlemagne", r: "Roi des Francs, empereur d'Occident", d: "vers 747 – 814", b: "Roi pendant plus de quarante ans, il étend son royaume de l'Italie à la Saxe et se fait couronner empereur à Rome, à Noël 800. Il installe sa cour à Aix-la-Chapelle." },
    { n: "Alcuin d'York", r: "Lettré, maître de l'école du palais", d: "vers 735 – 804", b: "Venu d'Angleterre, il enseigne à Charlemagne et à sa cour, relance les écoles et finit abbé de Saint-Martin de Tours. On lui attribue des devinettes mathématiques." },
    { n: "Rollon", r: "Chef viking, fondateur de la Normandie", d: "mort vers 930", b: "Après avoir ravagé la vallée de la Seine, il reçoit vers 911 la région de Rouen du roi Charles le Simple, se fait baptiser et devient le premier chef des Normands." }
  ]
};
